mapper.select:
/* 픽셀 캐릭터 단건 조회 */
SELECT 
  FROM PIXEL_CHAR
 WHERE PIXEL_CHAR_SN = #{pixelCharSn}
   AND DEL_YN = 'N'

/* 반려동물의 픽셀 캐릭터 조회 */
SELECT 
  FROM PIXEL_CHAR
 WHERE PET_SN = #{petSn}
   AND DEL_YN = 'N'

mapper.update:
/* 기본 캐릭터 대체 여부 변경 */
UPDATE PIXEL_CHAR
   SET BSC_CHAR_SBST_YN = #{bscCharSbstYn}
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE PIXEL_CHAR_SN = #{pixelCharSn}
   AND DEL_YN = 'N'

/* 맨몸 시트·배치값 저장 */
UPDATE PIXEL_CHAR
   SET BODY_SHEET_FILE_SN = #{bodySheetFileSn}
     , SHEET_SCALE = #{sheetScale}
     , SHEET_ORIGIN_X = #{sheetOriginX}
     , SHEET_ORIGIN_Y = #{sheetOriginY}
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE PIXEL_CHAR_SN = #{pixelCharSn}
   AND DEL_YN = 'N'

/* 착용 모습 대표 이미지 저장·삭제 : NULL이면 삭제 */
UPDATE PIXEL_CHAR
   SET WEAR_IMG_FILE_SN = #{wearImgFileSn}
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE PIXEL_CHAR_SN = #{pixelCharSn}
   AND DEL_YN = 'N'

/* 반려동물의 픽셀 캐릭터 삭제 */
UPDATE PIXEL_CHAR
   SET DEL_YN = 'Y'
     , MDFR_ID = #{actorId}
     , MDFCN_DT = NOW()
 WHERE PET_SN = #{petSn}
   AND DEL_YN = 'N'

/* 반려동물의 캐릭터 생성 작업 삭제 : 진행 중이던 작업은 이후 조회되지 않아 결과를 저장하지 않는다 */
UPDATE CHAR_CRT_JOB
   SET DEL_YN = 'Y'
     , MDFCN_DT = NOW()
 WHERE PET_SN = #{petSn}
   AND DEL_YN = 'N'

mapper.select:
/* 캐릭터 생성 작업 단건 조회 */
SELECT 
  FROM CHAR_CRT_JOB
 WHERE CHAR_CRT_JOB_SN = #{charCrtJobSn}
   AND DEL_YN = 'N'

/* 멱등 요청 ID로 캐릭터 생성 작업 조회 : 같은 키를 다시 쓰지 않도록 삭제된 작업도 본다 */
SELECT 
  FROM CHAR_CRT_JOB
 WHERE IDMPT_DMND_ID = #{idmptDmndId}

mapper.insert:
/* 캐릭터 생성 작업 등록 */
INSERT INTO CHAR_CRT_JOB
     ( PET_SN
     , MBR_SN
     , CRT_JOB_STTS_CD
     , IDMPT_DMND_ID
     , REG_DT
     , MDFCN_DT )
VALUES
     ( #{petSn}
     , #{mbrSn}
     , #{crtJobSttsCd}
     , #{idmptDmndId}
     , NOW()
     , NOW() )

mapper.update:
/* 캐릭터 생성 작업 시작 처리 */
UPDATE CHAR_CRT_JOB
   SET CRT_JOB_STTS_CD = #{aftrSttsCd}
     , PRCS_BGNG_DT = NOW()
     , MDFCN_DT = NOW()
 WHERE CHAR_CRT_JOB_SN = #{charCrtJobSn}
   AND CRT_JOB_STTS_CD = #{bfrSttsCd}

/* 캐릭터 생성 작업 종료 처리(성공·실패) */
UPDATE CHAR_CRT_JOB
   SET CRT_JOB_STTS_CD = #{aftrSttsCd}
     , FAIL_RSN = #{failRsn}
     , PRCS_END_DT = NOW()
     , MDFCN_DT = NOW()
 WHERE CHAR_CRT_JOB_SN = #{charCrtJobSn}
   AND CRT_JOB_STTS_CD IN

        #{bfrSttsCd}

mapper.select:
/* 시작 뒤 제한 시간을 넘긴 캐릭터 생성 작업 조회 */
SELECT CHAR_CRT_JOB_SN
  FROM CHAR_CRT_JOB
 WHERE CRT_JOB_STTS_CD = #{crtJobSttsCd}
   AND PRCS_BGNG_DT < NOW() - INTERVAL #{minutes} MINUTE
   AND DEL_YN = 'N'

mapper.update:
/* 캐릭터 생성 작업에 문의 연결 */
UPDATE CHAR_CRT_JOB
   SET OTO_INQRY_SN = #{otoInqrySn}
     , MDFCN_DT = NOW()
 WHERE CHAR_CRT_JOB_SN = #{charCrtJobSn}
   AND OTO_INQRY_SN IS NULL

mapper.insert:
/* 캐릭터 생성 작업 상태 변경 이력 등록 */
INSERT INTO CHAR_CRT_JOB_STTS_HSTRY
     ( CHAR_CRT_JOB_SN
     , MBR_SN
     , BFR_STTS_CD
     , AFTR_STTS_CD
     , CHG_RSN
     , REG_DT )
VALUES
     ( #{charCrtJobSn}
     , #{mbrSn}
     , #{bfrSttsCd}
     , #{aftrSttsCd}
     , #{chgRsn}
     , NOW() )

/* 캐릭터 사진 등록 */
INSERT INTO CHAR_PHOTO
     ( PIXEL_CHAR_SN
     , CHAR_CRT_JOB_SN
     , ATCH_FILE_SN
     , PHOTO_ROLE_CD
     , SORT_SEQ
     , NOW_INDCT_YN
     , REG_DT
     , MDFCN_DT )
VALUES
     ( #{pixelCharSn}
     , #{charCrtJobSn}
     , #{atchFileSn}
     , #{photoRoleCd}
     , #{sortSeq}
     , #{nowIndctYn}
     , NOW()
     , NOW() )

mapper.select:
/* 생성 작업의 역할별 사진 조회 */
SELECT 
  FROM CHAR_PHOTO
 WHERE CHAR_CRT_JOB_SN = #{charCrtJobSn}
   AND PHOTO_ROLE_CD = #{photoRoleCd}
   AND DEL_YN = 'N'
 ORDER BY SORT_SEQ
        , CHAR_PHOTO_SN
 LIMIT 1

/* 캐릭터의 현재 표시 사진 조회 */
SELECT 
  FROM CHAR_PHOTO
 WHERE PIXEL_CHAR_SN = #{pixelCharSn}
   AND NOW_INDCT_YN = 'Y'
   AND DEL_YN = 'N'

/* 캐릭터 사진 단건 조회 */
SELECT 
  FROM CHAR_PHOTO
 WHERE CHAR_PHOTO_SN = #{charPhotoSn}
   AND DEL_YN = 'N'

mapper.update:
/* 캐릭터의 현재 표시 사진 해제 */
UPDATE CHAR_PHOTO
   SET NOW_INDCT_YN = 'N'
     , MDFCN_DT = NOW()
 WHERE PIXEL_CHAR_SN = #{pixelCharSn}
   AND NOW_INDCT_YN = 'Y'

/* 선택한 보유 아이템 착용 */
UPDATE HLD_ITEM
   SET EQUIP_YN = 'Y'
     , MDFCN_DT = NOW()
 WHERE PIXEL_CHAR_SN = #{pixelCharSn}
   AND DEL_YN = 'N'
   AND HLD_ITEM_SN IN

        #{hldItemSn}

/* 캐릭터의 착용 시트 전부 삭제 */
UPDATE CHAR_ITEM_SHEET
   SET DEL_YN = 'Y'
     , MDFCN_DT = NOW()
 WHERE PIXEL_CHAR_SN = #{pixelCharSn}
   AND DEL_YN = 'N'

/* 아이템의 착용 시트 전부 삭제 */
UPDATE CHAR_ITEM_SHEET
   SET DEL_YN = 'Y'
     , MDFCN_DT = NOW()
 WHERE ITEM_SN = #{itemSn}
   AND DEL_YN = 'N'

mapper.select:
/* 캐릭터의 착용 시트 파일 여부 */
SELECT COUNT(*)
  FROM CHAR_ITEM_SHEET
 WHERE PIXEL_CHAR_SN = #{pixelCharSn}
   AND ATCH_FILE_SN = #{atchFileSn}
   AND DEL_YN = 'N'
